/**
 * Tiny embedded samples used to probe DECODE support at runtime.
 *
 * Phase 0 found that decode and encode support disagree, and that the answer is
 * platform-specific: on macOS AVIF and TIFF decode but never encode, and on
 * Linux they do neither. So decode cannot be inferred from encode, and neither
 * can be inferred from the docs — both get probed on the machine that is
 * actually running.
 *
 * JPEG/PNG/WebP are not listed here: the engine can encode them, so the probe
 * generates those samples itself rather than shipping constants.
 *
 * Each sample is a 2x2 image, base64. Generated by `benchmarks/genfix.ts`.
 */
export const DECODE_PROBE_SAMPLES: Readonly<Record<string, string>> = {
  gif:
    "R0lGODlhAgACAIIAAExpcQD/AP//AP8AAAAA/wAAAAAAAAAAACH5BAUAAAAALAAAAAACAAIAAAMDOEGSADs=",
  tiff:
    "",
  avif:
    "",
  heic:
    "",
};
